document.addEventListener("DOMContentLoaded", () => {
  sincronizarDirectorioServidoresSupabase();
});

// Descarga cualquier actualización desde la tabla anc_servidores de Supabase y guarda en caché local
window.sincronizarDirectorioServidoresSupabase = async function() {
  try {
    if (!window.SupabaseANC) return;
    const res = await window.SupabaseANC.request("anc_servidores", "GET", "activo=eq.true&order=apellidos_nombres.asc&limit=1000");
    if (res.data && res.data.length > 0) {
      window.ANC_SERVIDORES_DB = res.data;
      localStorage.setItem("anc_servidores_cache_v1", JSON.stringify(res.data));
    }
  } catch (e) {
    console.warn("Usando directorio precargado local (355 servidores ANC-MP):", e);
  }
};

// Buscador inteligente sin tildes para autocompletar por DNI o por Apellidos y Nombres
window.buscarServidoresANC = function(termino, limite = 8) {
  if (!termino || String(termino).trim().length < 2) return [];
  const norm = (s) => String(s || "").normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase().trim();
  const q = norm(termino);
  const palabras = q.split(/\s+/);
  const lista = window.ANC_SERVIDORES_DB || [];

  return lista.filter(srv => {
    const texto = norm(`${srv.dni} ${srv.apellidos_nombres} ${srv.cargo} ${srv.unidad_organica}`);
    return palabras.every(p => texto.includes(p));
  }).slice(0, limite);
};

// Vincula un buscador predictivo flotante a cualquier input de Nombre o DNI, permitiendo también escritura manual libre
window.vincularAutocompletadoServidor = function(inputId, callbackSeleccion) {
  const inputEl = document.getElementById(inputId);
  if (!inputEl) return;

  inputEl.setAttribute("autocomplete", "off");
  const parent = inputEl.parentElement;
  if (parent) parent.style.position = "relative";

  let boxSugerencias = document.getElementById(`sug-box-${inputId}`);
  if (!boxSugerencias) {
    boxSugerencias = document.createElement("div");
    boxSugerencias.id = `sug-box-${inputId}`;
    boxSugerencias.style.cssText = "position:absolute; left:0; right:0; top:100%; z-index:950; background:#FFFFFF; border:2px solid #F59E0B; border-radius:12px; box-shadow:0 10px 25px rgba(15,23,42,0.18); max-height:230px; overflow-y:auto; display:none; margin-top:4px;";
    parent.appendChild(boxSugerencias);
  }

  inputEl.addEventListener("input", () => {
    const val = inputEl.value.trim();
    const resultados = window.buscarServidoresANC(val, 8);
    if (resultados.length === 0) {
      boxSugerencias.style.display = "none";
      return;
    }

    boxSugerencias.innerHTML = resultados.map((srv, idx) => `
      <div data-idx="${idx}" style="padding:9px 12px; border-bottom:1px solid #F1F5F9; cursor:pointer; font-size:0.8rem; line-height:1.3;">
        <div style="font-weight:800; color:#0F172A;">${srv.apellidos_nombres} <span style="color:#D97706;">(DNI: ${srv.dni})</span></div>
        <div style="font-size:0.72rem; color:#475569;">${srv.cargo} • ${srv.regimen_vinculo}</div>
        <div style="font-size:0.7rem; color:#0284C7; font-weight:700;">[${srv.codigo_dependencia}] ${srv.unidad_organica}</div>
      </div>
    `).join("") + `
      <div data-manual="1" style="padding:7px 12px; background:#FFFBEB; color:#92400E; font-size:0.72rem; font-weight:800; text-align:center; cursor:pointer;">
        ✍️ Cerrar sugerencias y mantener texto escrito manualmente
      </div>
    `;

    boxSugerencias.style.display = "block";

    boxSugerencias.querySelectorAll("[data-idx]").forEach(itemEl => {
      itemEl.addEventListener("click", () => {
        const seleccionado = resultados[Number(itemEl.getAttribute("data-idx"))];
        boxSugerencias.style.display = "none";
        if (typeof callbackSeleccion === "function" && seleccionado) {
          callbackSeleccion(seleccionado);
        }
      });
    });

    const btnManual = boxSugerencias.querySelector("[data-manual]");
    if (btnManual) {
      btnManual.addEventListener("click", () => {
        boxSugerencias.style.display = "none";
      });
    }
  });

  document.addEventListener("click", (e) => {
    if (e.target !== inputEl && !boxSugerencias.contains(e.target)) {
      boxSugerencias.style.display = "none";
    }
  });
};
